const fs = require('fs');

const MOD = 1000000007n;

function modPow(base, exp, mod) {
    let result = 1n;
    base = base % mod;
    while (exp > 0n) {
        if (exp % 2n === 1n) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp = exp / 2n;
    }
    return result;
}

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    let idx = 0;

    const t = parseInt(input[idx++], 10);
    const out = [];

    for (let i = 0; i < t; i++) {
        const n = BigInt(input[idx++]);
        const k = BigInt(input[idx++]);
        const ans = modPow(n, k, MOD);
        out.push(ans.toString());
    }

    console.log(out.join('\n'));
}

main();

